def remove_duplicates(items):
    seen = set()  # Initialize an empty set to keep track of seen elements.
    result = []  # Initialize an empty list to store the unique elements.

    # Iterate through each item in the input list.
    for item in items:
        # Check if the current item has not been seen before.
        if item not in seen:
            result.append(item)  # Add the item to the result list.
            seen.add(item)  # Add the item to the set of seen elements.
    return result  # Return the list with duplicates removed.

