def remove_duplicates(items):
    seen = set()  # Inicializa un conjunto vacío para llevar un registro de los elementos vistos.
    result = []  # Inicializa una lista vacía para almacenar los elementos únicos.

    # Itera a través de cada elemento en la lista de entrada.
    for item in items:
        # Comprueba si el elemento actual no ha sido visto antes.
        if item not in seen:
            result.append(item)  # Agrega el elemento a la lista de resultados.
            seen.add(item)  # Agrega el elemento al conjunto de elementos vistos.
    return result  # Devuelve la lista con los duplicados eliminados.

