def update_inventory(inventory, item_name, quantity):
    # Check if the item already exists in the inventory dictionary.
    if item_name in inventory:
        # If the item exists, increment its current quantity.
        inventory[item_name] += quantity
    else:
        # If the item does not exist, add it to the inventory.
        inventory[item_name] = quantity
    # Return the modified inventory dictionary.
    return inventory

# Example 1: Updating an existing item.
# Initial inventory for the first test case.
initial_inventory_1 = {'apple': 10}
# Call the function to update 'apple' quantity.
updated_inventory_1 = update_inventory(initial_inventory_1, 'apple', 5)
# Expected result: {'apple': 15}

# Example 2: Adding a new item.
# Initial inventory for the second test case.
initial_inventory_2 = {'apple': 10}
# Call the function to add 'banana' to the inventory.
updated_inventory_2 = update_inventory(initial_inventory_2, 'banana', 3)
# Expected result: {'apple': 10, 'banana': 3}

# Example 3: Updating an item that doesn't exist, then exists.
# Starting with an empty inventory for a more complex test.
empty_inventory = {}
# Add 'orange' to the empty inventory.
updated_inventory_3 = update_inventory(empty_inventory, 'orange', 7)
# Update 'orange' again in the same inventory.
updated_inventory_3 = update_inventory(updated_inventory_3, 'orange', 3)
# Expected result: {'orange': 10}

