def update_inventory(inventory, item_name, quantity):
    # Comprueba si el artículo ya existe en el diccionario de inventario.
    if item_name in inventory:
        # Si el artículo existe, incrementa su cantidad actual.
        inventory[item_name] += quantity
    else:
        # Si el artículo no existe, añádelo al inventario.
        inventory[item_name] = quantity
    # Devuelve el diccionario de inventario modificado.
    return inventory

# Ejemplo 1: Actualizando un artículo existente.
# Inventario inicial para el primer caso de prueba.
initial_inventory_1 = {'apple': 10}
# Llama a la función para actualizar la cantidad de 'apple'.
updated_inventory_1 = update_inventory(initial_inventory_1, 'apple', 5)
# Resultado esperado: {'apple': 15}

# Ejemplo 2: Añadiendo un nuevo artículo.
# Inventario inicial para el segundo caso de prueba.
initial_inventory_2 = {'apple': 10}
# Llama a la función para añadir 'banana' al inventario.
updated_inventory_2 = update_inventory(initial_inventory_2, 'banana', 3)
# Resultado esperado: {'apple': 10, 'banana': 3}

# Ejemplo 3: Actualizando un artículo que no existe, luego existe.
# Comenzando con un inventario vacío para una prueba más compleja.
empty_inventory = {}
# Añade 'orange' al inventario vacío.
updated_inventory_3 = update_inventory(empty_inventory, 'orange', 7)
# Actualiza 'orange' de nuevo en el mismo inventario.
updated_inventory_3 = update_inventory(updated_inventory_3, 'orange', 3)
# Resultado esperado: {'orange': 10}
